// ===========================================================================
// Minebricks — ore chain: chalcopyrite ore block + intermediary items
// Spec: Fina 2026-10-28 ~22:03Z ("Build the end to end for Chalcopyerite...
// the machines needed to get to T4"; EE ruled extraneous same message —
// item forms are ours, generated from the MATERIALS x PARTS array).
//
// TEXTURES: byte-wise programmer art, generated by
//   scripts/gen_ore_textures.py (deterministic, re-run to extend the array)
//   -> kubejs/assets/kubejs/textures/{item,block}/chalcopyrite_*.png
// Models: ItemBuilder/BlockBuilder are ModelledBuilderBase subclasses (jar-
// verified build 377: texture(String)/parentModel on the base) — each builder
// pins its texture explicitly; KubeJS generates the model JSON from it.
//
// NAMESPACES: items/blocks under kubejs: (the scanner precedent, verified in
// this pack). MBD2 machines stay minebricks:. The ore block joins #c:ores
// (block+item, via tagBoth) — that single membership feeds the Silent's Gear
// hammer config, the chunk ledger's scanner_targets census (#c:ores is a
// member), and the wider ecosystem. TEMPORARY self-drop loot: the block drops
// itself (vanilla ore raw-drop + Fortune curve is the real loot-table pass,
// hers to dial; flagged in NEXT-UP).
//
// Counts/durations anywhere in this chain are TEMPORARY (her 64x-placeholder
// convention) until the roster matrix ruling.
//
// Verification trail (jar-verified build 377, 2026-10-29):
//   StartupEvents.registry           — StartupEvents precedent (scanner item)
//   ItemBuilder.displayName/maxStackSize — ItemBuilder.class method table
//   ModelledBuilderBase.texture      — ModelledBuilderBase.class method table
//   BlockBuilder.hardness/resistance/requiresTool/stoneSoundType/tag/tagBoth
//                                    — BlockBuilder.class method table (93)
//   KubeResourceLocation string coercion — RegistryKubeEvent.create(ctx, KRL)
// House rules: IIFE scope isolation (0.4.8); declarations at function-body
// top only; failure paths to console.info.
// ===========================================================================

;
(function () {

  var CHALC = 'chalcopyrite'

  // (suffix, display name) — mirrors the PARTS array in gen_ore_textures.py
  var ITEMS = [
    ['raw', 'Raw Chalcopyrite'],
    ['crushed', 'Crushed Chalcopyrite'],
    ['washed', 'Washed Chalcopyrite'],
    ['milled', 'Milled Chalcopyrite'],
    ['concentrate', 'Chalcopyrite Concentrate'],
    ['roasted', 'Roasted Chalcopyrite']
  ]

  StartupEvents.registry('item', function (event) {
    var i = 0
    for (i = 0; i < ITEMS.length; i++) {
      event.create(CHALC + '_' + ITEMS[i][0])
        .displayName(ITEMS[i][1])
        .texture('kubejs:item/' + CHALC + '_' + ITEMS[i][0])
    }
    console.info('[ore-chain] registered ' + ITEMS.length + ' chalcopyrite intermediary items')
  })

  StartupEvents.registry('block', function (event) {
    event.create(CHALC + '_ore')
      .displayName('Chalcopyrite Ore')
      .texture('kubejs:block/' + CHALC + '_ore')
      .hardness(3.0)
      .resistance(3.0)
      .requiresTool()
      .stoneSoundType()
      .tagBoth('c:ores')
      .tagBlock('minecraft:mineable/pickaxe')
    console.info('[ore-chain] registered kubejs:' + CHALC + '_ore (c:ores + mineable/pickaxe, self-drop TEMPORARY)')
  })

})()
